use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved grant extension: record the input received on every call.
        state_rw::put("last-input", &feed_url);

        // Read the time.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. Transport failures come back as a value and
        // count as zero characters fetched. An out-of-allowlist URL traps at
        // the boundary by design.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notify. The contract requires notified == true, so retry a few
        // times. If the notifier still refuses, trap rather than emit an
        // output that violates the contract.
        let message = format!(
            "heartbeat at {}: fetched {} chars from {}",
            seconds, fetched, feed_url
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
